"""Self-contained, offline, source-named META145 browser; no telemetry/network calls."""
from __future__ import annotations
import json,sqlite3
from pathlib import Path
from .glyph import typed_route


def render_viewer(db_path,meta_path,sphere_path,out_path):
    db=sqlite3.connect(db_path)
    node_rows=db.execute('SELECT hsn,sphere,name,role,record_digest,axg1,gf7 FROM nodes ORDER BY hsn').fetchall()
    sphere_rows=db.execute('SELECT hsn,house,name,role,review_digest FROM spheres ORDER BY hsn').fetchall()
    houses=db.execute('SELECT hsn,name FROM houses ORDER BY hsn').fetchall()
    topics=db.execute('SELECT c.hsn,c.topic_id,t.label,c.rank,c.relation FROM topic_candidates c JOIN topics t ON t.id=c.topic_id ORDER BY c.hsn,c.rank,c.topic_id').fetchall()
    db.close()
    meta=json.loads(Path(meta_path).read_text())
    briefs=json.loads(Path(sphere_path).read_text())
    route={r[0]:typed_route(r[0],meta['source_reg_sha256']) for r in node_rows}
    node_topics={}
    for n,tid,title,rank,relation in topics:node_topics.setdefault(n,[]).append({'id':tid,'title':title,'rank':rank,'relation':relation})
    view={'nodes':[{'id':r[0],'sphere':r[1],'name':r[2],'role':r[3],'digest':r[4],'axg':r[5],'gf':r[6]} for r in node_rows],
          'spheres':[{'id':r[0],'house':r[1],'name':r[2],'role':r[3],'digest':r[4]} for r in sphere_rows],
          'houses':[{'id':r[0],'name':r[1]} for r in houses], 'topics':node_topics,
          'briefs':[{k:v for k,v in b.items() if k in ('sphere','name','role','query_terms','top_cross_house_candidates','unique_cross_candidate_count_so_far','receipt_sha256')} for b in briefs],
          'meta':meta,'routes':route}
    payload=json.dumps(view,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
    html=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Atlas META145C — Glyph Knowledge Observatory</title>
<style>
:root{color-scheme:dark;--bg:#091624;--panel:#11293b;--card:#18394a;--line:#395769;--text:#e6f6f3;--muted:#abc7c8;--accent:#90ded4;--warning:#e9c882}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.55 system-ui,Segoe UI,sans-serif}main{max-width:1240px;margin:auto;padding:22px}h1{font-size:clamp(1.55rem,3vw,2.7rem);line-height:1.2;margin:5px 0}h2{font-size:1.18rem;margin:0 0 8px}p{margin:7px 0 12px;color:var(--muted)}small{color:var(--muted)}strong{color:var(--text)}.eyebrow{color:var(--accent);letter-spacing:.1em;font-size:.74rem;font-weight:800}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin:19px 0}.metric,.panel,.detail{background:var(--panel);border:1px solid var(--line);border-radius:13px;padding:15px}.metric b{font-size:1.65rem;display:block;color:var(--text)}.metric small{display:block}.columns{display:grid;grid-template-columns:minmax(0,1fr) minmax(340px,.83fr);gap:13px}.filters{display:flex;gap:8px;flex-wrap:wrap;margin:8px 0 14px}input,select,button{font:inherit;border:1px solid var(--line);border-radius:8px;background:#0d2030;color:var(--text);padding:10px}input{flex:2;min-width:175px}select{flex:1;min-width:140px}button{cursor:pointer}button:hover,button:focus-visible{border-color:var(--accent);outline:2px solid transparent}.node{width:100%;text-align:left;margin:4px 0;display:flex;justify-content:space-between;gap:12px}.node[aria-pressed=true]{border-color:var(--accent);background:#24475a}.list{max-height:70vh;overflow:auto}.pill{font-size:11px;padding:2px 6px;background:#204257;color:#d7eeee;border-radius:7px}.row{display:flex;justify-content:space-between;align-items:center;gap:10px}code{overflow-wrap:anywhere;white-space:normal;color:#bfe8e4}.detail{position:sticky;top:8px;max-height:91vh;overflow:auto}.warning{color:var(--warning)}.fade{opacity:.8}.slot{padding:8px 0;border-bottom:1px solid var(--line)}.nowrap{white-space:nowrap}canvas{width:100%;max-height:190px;border:1px solid var(--line);border-radius:7px}#pager{display:flex;gap:8px;margin-top:10px}.topicbox{max-height:200px;overflow:auto}.svgstatus{color:var(--warning)}@media(max-width:850px){.columns{grid-template-columns:1fr}.detail{position:static;max-height:none}.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}
</style></head><body><main><header><div class="eyebrow">ATLAS / ARIADNE / META145C · OWNER-PRIVATE OFFLINE</div><h1>144 unique perspectives.<br>One traceable knowledge fabric.</h1><p>Original HSN source names · 1,728 nodes · typed glyph/plate-mode analogy · OpenAlex candidate context · source-indexed cumulative synthesis. <strong>Nothing on this page is hosted, physically measured cymatics, resident authentication, accepted semantic equivalence, model training or CANON.</strong></p></header>
<section class="metrics" aria-label="Execution metrics"><div class="metric"><b id="numNodes">1,728</b><small>Exact source nodes</small></div><div class="metric"><b id="numSpheres">144</b><small>Source-specific Sphere lenses</small></div><div class="metric"><b id="numPairs">248,832</b><small>Offline comparisons</small></div><div class="metric"><b id="speed">–</b><small>Local CPU lexical index speed ratio (warm)</small></div></section>
<div class="columns"><section class="panel"><h2>Explore source coordinates</h2><div class="filters"><input id="q" type="search" aria-label="Search node or coordinate" placeholder="Search Plasma confinement or H01.S05.N10"><select id="house" aria-label="House filter"><option value="">All 12 Houses</option></select><select id="sphere" aria-label="Sphere filter"><option value="">All 144 Spheres</option></select><select id="role" aria-label="Sphere role"><option value="">Both roles</option><option value="DOMAIN_SPECIALIZATION">Domain</option><option value="EPISTEMIC_META">Method</option></select></div><div id="count" role="status" aria-live="polite"></div><div class="list" id="list"></div><div id="pager"><button id="prev" type="button">Previous 48</button><button id="next" type="button">Next 48</button></div></section><section class="detail" aria-label="Selected source card"><h2 id="selName">Select a source node</h2><div class="fade" id="selId">HSN exact coordinate</div><p id="selRole"></p><p id="selSphere"></p><div class="slot"><strong>Authored, reversible AXG1 address</strong><div><code id="selAxg"></code></div><small>New project display token, not recovered historical KG8.</small></div><div class="slot"><strong>GF7 plate-mode position (analogy only)</strong><div><code id="selGF"></code></div><p id="selPlate"></p><canvas id="plate" width="384" height="192" aria-label="Synthetic analytical plate sinusoidal mode pattern"></canvas><small class="svgstatus">Synthetic analytic plate display. Not a measured acoustic wave or a physical property of this HSN node.</small></div><div class="slot"><strong>OpenAlex historical topic candidates</strong><div id="topicCount" class="fade"></div><div class="topicbox" id="topics"></div><div class="row"><button id="moreTopics" type="button">Show 20 more</button></div><small>No topic candidate is automatically SAME_AS or an academic authority.</small></div><div class="slot"><strong>Sphere's unique computational perspective</strong><div id="briefText"></div><small id="briefReceipt"></small></div><div class="slot"><strong>Functional-memory boundary</strong><p>Append-only local Work review events can reprioritize investigation after explicit input, with SHA-linked retraction and restart. No background task, hosted IAM, model-weight update or automatic truth promotion.</p></div></section></div>
<footer><p id="edition"></p><p>Privacy: zero network calls, tracking, remote fonts, localStorage or browser submissions. The accessible text fields are the authoritative coordinate output; the plate drawing is optional and decorative.</p></footer></main>
<script>const DATA=__PAYLOAD__;
const $=id=>document.getElementById(id);const byId=Object.fromEntries(DATA.spheres.map(s=>[s.id,s]));const houseNames=Object.fromEntries(DATA.houses.map(h=>[h.id,h.name]));const briefs=Object.fromEntries(DATA.briefs.map(b=>[b.sphere,b]));let filtered=DATA.nodes,offset=0,selected=null,topicLimit=20;
DATA.houses.forEach(h=>{let o=document.createElement('option');o.value=h.id;o.textContent=h.id+' '+h.name;$('house').append(o)});DATA.spheres.forEach(s=>{let o=document.createElement('option');o.value=s.id;o.textContent=s.id+' '+s.name;$('sphere').append(o)});
$('speed').textContent=DATA.meta.performance.median_speed_ratio+'×';$('edition').textContent='Pinned Ariadne v0.7 SHA-256 '+DATA.meta.source_reg_sha256+' · OpenAlex historical digest '+DATA.meta.historical_openalex_sha256+' · META synthesis receipt '+DATA.meta.meta_receipt_sha256+' · no host rights';
const txt=(id,value)=>{$(id).textContent=String(value||'')};
function redraw(){const needle=$('q').value.trim().toLowerCase(),h=$('house').value,s=$('sphere').value,r=$('role').value;filtered=DATA.nodes.filter(n=>(!h||n.id.startsWith(h+'.'))&&(!s||n.sphere===s)&&(!r||n.role===r)&&(!needle||n.id.toLowerCase().includes(needle)||n.name.toLowerCase().includes(needle)||byId[n.sphere].name.toLowerCase().includes(needle)));offset=Math.min(offset,Math.max(0,Math.floor((filtered.length-1)/48)*48));$('list').replaceChildren();filtered.slice(offset,offset+48).forEach(n=>{const b=document.createElement('button');b.type='button';b.className='node';b.setAttribute('aria-pressed',n.id===selected?'true':'false');const l=document.createElement('span');l.textContent=n.id+' · '+n.name;const x=document.createElement('span');x.className='pill nowrap';x.textContent=n.role==='EPISTEMIC_META'?'Method':'Domain';b.append(l,x);b.onclick=()=>select(n.id);$('list').append(b)});txt('count',filtered.length+' matched source nodes · showing '+(filtered.length?offset+1:0)+'–'+Math.min(offset+48,filtered.length));$('prev').disabled=offset===0;$('next').disabled=offset+48>=filtered.length}
function drawPlate(mode){const c=$('plate'),g=c.getContext('2d');if(!g)return;const w=c.width,h=c.height,img=g.createImageData(w,h),mx=mode[0],my=mode[1];for(let y=0;y<h;y++)for(let x=0;x<w;x++){let a=Math.sin(mx*Math.PI*(x+.5)/w)*Math.sin(my*Math.PI*(y+.5)/h);let idx=4*(y*w+x),v=Math.round(135+110*a);img.data[idx]=Math.round(25+45*a*a);img.data[idx+1]=v;img.data[idx+2]=Math.round(130+80*Math.abs(a));img.data[idx+3]=255}g.putImageData(img,0,0)}
function renderTopics(){const n=DATA.topics[selected]||[];txt('topicCount',n.length+' total historical topic candidates · '+Math.min(n.length,topicLimit)+' shown · '+Math.max(0,n.length-topicLimit)+' omitted');$('topics').replaceChildren();n.slice(0,topicLimit).forEach(t=>{let p=document.createElement('div');p.className='slot';p.textContent=t.id+' · '+t.title+' · candidate rank '+t.rank;$('topics').append(p)});$('moreTopics').disabled=topicLimit>=n.length}
function select(id){const n=DATA.nodes.find(x=>x.id===id);if(!n)return;selected=id;topicLimit=20;txt('selName',n.name);txt('selId',n.id+' · Original source record '+n.digest);txt('selRole',n.role+' · '+houseNames[n.id.slice(0,3)]);txt('selSphere',n.sphere+' '+byId[n.sphere].name);txt('selAxg',n.axg);txt('selGF',n.gf);const route=DATA.routes[id],gf=route.gf7_model;txt('selPlate','Synthetic '+gf.material+' / aspect '+gf.aspect_b_over_a+' / mode ('+gf.mode_indices.join(',')+') / band '+gf.band_hz[0]+'–'+gf.band_hz[1]+' Hz. No physical calibration.');drawPlate(gf.mode_indices);renderTopics();const br=briefs[n.sphere];txt('briefText',br?.name+' · '+br?.role+' · token lens: '+(br?.query_terms||[]).join(', ')+' · '+(br?.top_cross_house_candidates||[]).length+' highest-overlap cross-House candidates for further review.');txt('briefReceipt',br?.receipt_sha256);redraw()}
['q','house','sphere','role'].forEach(id=>$(id).addEventListener(id==='q'?'input':'change',()=>{offset=0;redraw()}));$('prev').onclick=()=>{offset=Math.max(0,offset-48);redraw()};$('next').onclick=()=>{offset+=48;redraw()};$('moreTopics').onclick=()=>{topicLimit+=20;renderTopics()};redraw();select('H01.S05.N10');</script></body></html>'''
    html=html.replace('__PAYLOAD__',payload)
    Path(out_path).write_text(html,encoding='utf-8')
    return {'nodes':len(node_rows),'spheres':len(sphere_rows),'house_count':len(houses),
            'topic_edges':len(topics),'html_bytes':Path(out_path).stat().st_size,'no_network_urls':True}
